    "color": {
      "type": "string",
      "pattern": "^[a-z]+$"
    },
    "vehicle-type": {
      "type": "string",
      "pattern": "^[a-z]+$",
      "enum": ["car", "bike", "scooter"]
    },
    "features": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[a-z]+$"
      }
    }
  },
  "required": ["make", "model", "year", "color", "vehicle-type"]
}
